%[text] %[text:anchor:T_1EFBF752] # Distributions
%[text] 
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] 
%%
%[text] %[text:anchor:H_C1E0A0EC] ## Preparing  MATLAB
close all
clearvars
clc

mmSetFigPublication %[output:98805e63]
%%
%[text] ## Normal Data
%[text] generating normal data
mu = 63.7; % mean height of women as reported on google
sigma = 2.5; % standard deviation
heights = sigma.*randn(1000,1)+mu; % generate random numbers with mean mu and std sigma
histogram(heights) % plot histogram %[output:1d3130d1]
xline(mu,'--r','mean') %[output:1d3130d1]
title(sprintf("Average Female Height = %1.2f±%1.2f",mu,sigma)) %[output:1d3130d1]
xlabel("Height (in)") %[output:1d3130d1]
%%
%[text] ### Visualizing Normal Data
%[text] box plot vs histogram
figure(Visible="on") %[output:9c71dd70]
tiledlayout("horizontal","TileSpacing","compact") %[output:9c71dd70]

nexttile % bar plot %[output:9c71dd70]
hb = boxchart(heights); % box plot %[output:9c71dd70]
yline(mu,'r:','label','mean'); %[output:9c71dd70]
ylabel("Height (in)") %[output:9c71dd70]
title("Box plot") %[output:9c71dd70]
ylim([55 75]) % y limits %[output:9c71dd70]
hb.Parent.XAxis.Visible='off'; % turn off x-axis %[output:9c71dd70]
grid minor % turn on grid %[output:9c71dd70]

nexttile % histogram %[output:9c71dd70]
histogram(heights,Orientation="horizontal") % histogram %[output:9c71dd70]
hy = yline(mu,'r:'); %[output:9c71dd70]
title("Histogram") %[output:9c71dd70]
ylim([55 75]) %[output:9c71dd70]

sgtitle("Female Heights",fontsize=18) %[output:9c71dd70]
%%
%[text] ### Small sample size and the Normal Distribution
%[text] Even if a sample comes from a large, normally distributed population (like the heights of all Women), you likely won't get a normal distribution in the sample if your sample size is too small.
%[text] [Normal distribution and sample size](https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3915399/#:~:text=When%20the%20sample%20size%20increases,is%2030%20%5BFigure%201e%5D.)
%[text] Consider the following
clf %[output:72e50424]
female.mu = 63.7;
female.sigma = 2.5;


for n=[5 10 20 25 30 100] %[output:group:45c4c052]

  female.height = female.sigma * randn(n,1) + female.mu;

  nexttile %[output:72e50424]
  % histogram(female.height,10)
  histfit(female.height,10);
  colororder("glow12")
  title(sprintf('n = %d',n))
  xlim([40 80])
end %[output:group:45c4c052]
%[text] - Here we plot the histogram of a female heights with an increasing sample size (n)
%[text] - Try running the for loop several times to get a feel for the distributions
%[text] - We really don't start to see a normal distribution until sample size \>= 25 \
%%
figure(Visible="on") %[output:43985536]
tiledlayout("horizontal") %[output:43985536]

nexttile % swarm chart %[output:43985536]
mmBoxSwarm([],heights); % overlay box and swarm charts %[output:43985536]
ylim([55 75]) % set y limits %[output:43985536]
title("Swarm") %[output:43985536]
grid minor  %[output:43985536]

nexttile % violin chart %[output:43985536]
hc = mmBoxSwarm([],heights,"PlotType",'violin'); % overlay box and violin %[output:43985536]
ylim([55 75]) % set y limits %[output:43985536]
title("Violin") %[output:43985536]
grid minor %[output:43985536]

sgtitle("Female Heights",fontsize=18) %[output:43985536]
%%
%[text] %[text:anchor:H_4E8CB358] ## Generating Skewed data
%[text] The following data is based on this [site](https://www.mathworks.com/help/stats/exploratory-analysis-of-data.html)
rng default  % For reproducibility of random numbers
left.x = [normrnd(4,1,1,100),normrnd(6,0.5,1,200)]; % left skewed data
right.x = wblrnd(6,1,300,1); % right skewed data
%%
%[text] ### HistFit Skewed Data
%[text] #### Plot Left-skewed data
figure; %[output:509161cd]
hf = histfit(left.x) %[output:509161cd] %[output:49aa4a41]
%[text] - Does this look like a normal curve? Not well fit by the normal curve
%[text] - This is often referred to as skewed to the left because of the long tail on the left side of the peak \
%%
%[text] #### Plot Right Skewed Data
figure %[output:0814f077]
histfit(right.x) %[output:0814f077]
%[text] %[text:anchor:TMP_1608] - Again, the data is not well fit by the normal curve
%[text] - Here, the tail is to the right of the peak  \
%%
%[text] %[text:anchor:H_D8A00CBC] #### Mean vs Median
%[text] In Normal Data, mean = median. In skewed data, that is not the case
figure(Visible="on") %[output:2474c488]
tiledlayout("horizontal") %[output:2474c488]

nexttile % Plot Left Skewed Data %[output:2474c488]
hh = histogram(left.x, FaceAlpha=0.15); % histogram left data %[output:2474c488]
hh.FaceAlpha = 0.25; % box transparency %[output:2474c488]
hh.EdgeAlpha = 0.25; % edge transparency %[output:2474c488]
title("Left Skewed") %[output:2474c488]

hold on % add left vertical lines %[output:2474c488]
left.mean = mean(left.x); % calc left mean
left.median = median(left.x); % calc left median
xline(left.mean,'k-',LineWidth=1,Alpha=1) % plot left mean vert line %[output:2474c488]
xline(left.median,'r:',LineWidth=1.5) % plot left median vert line %[output:2474c488]

nexttile % Plot Right Skewed Data %[output:2474c488]
hh = histogram(right.x); % histogram right %[output:2474c488]
hh.FaceAlpha = 0.25; % box transparency %[output:2474c488]
hh.EdgeAlpha = 0.25; % edge transparency %[output:2474c488]

hold on % add right vertical lines %[output:2474c488]
right.mean = mean(right.x); % calc right mean
right.median = median(right.x); % calc right median
xline(right.mean,'k-',LineWidth=1,Alpha=1) % plot right mean vert line %[output:2474c488]
xline(right.median,'r:',LineWidth=1.5) % plot right median vert line %[output:2474c488]
title('Right Skewed') %[output:2474c488]
legend('data','mean','median') % add legend %[output:2474c488]
%[text] - The mean (black) and median (red) do not overlap
%[text] - The median is closer to the higher frequency data
%[text] - This type of plot is know as right skewed \
%%
%[text] %[text:anchor:H_911B45A9] ### box plots
%[text] Notice that the median is not quite in the center of the box 
figure(Visible="on") %[output:34ccdd8c]
tiledlayout("horizontal") %[output:34ccdd8c]

nexttile % plot left skewed data %[output:34ccdd8c]
hb = boxchart(left.x); % box plot   %[output:34ccdd8c]
hb.Parent.XAxis.Visible='off'; % hide x-axis %[output:34ccdd8c]
grid on % turn on grid %[output:34ccdd8c]

title("Left Skewed") %[output:34ccdd8c]

nexttile % plot right skewed data %[output:34ccdd8c]
hb = boxchart(right.x); % box plot %[output:34ccdd8c]
hb.Parent.XAxis.Visible='off'; % turn off x-axis %[output:34ccdd8c]
grid on % turn on grid %[output:34ccdd8c]

title("Right Skewed") %[output:34ccdd8c]
%[text] The lack of symmetry in the whiskers and outliers indicate a the lack of symmetry in the sample data values.
%[text] - **Right Skewed:** longer lower tail and lower outliers (circular markers)
%[text] - **Left Skewed:** longer top tail with higher outliers \
%[text] 
%%
%[text] %[text:anchor:H_C5ECF840] ### Swarm chart
%[text] The shape of the swarm chart looks skewed
figure(Visible="on") %[output:2ca49670]
tiledlayout("horizontal") %[output:2ca49670]

nexttile % plot Left Skewed %[output:2ca49670]
hold on %[output:2ca49670]
swarmchart(ones(1,numel(left.x)),left.x,'filled',MarkerFaceAlpha=0.5) % swarm %[output:2ca49670]
hb = boxchart(ones(1,numel(left.x)),left.x,BoxFaceColor='k',BoxFaceAlpha=0.1); % box %[output:2ca49670]
hb.Parent.XAxis.Visible='off'; %[output:2ca49670]
grid on %[output:2ca49670]

title("Left Skewed") %[output:2ca49670]

nexttile % plot Right skewed %[output:2ca49670]
hold on %[output:2ca49670]
swarmchart(ones(1,300),right.x,'filled',MarkerFaceAlpha=0.5) % swarm %[output:2ca49670]
hb = boxchart(ones(1,300),right.x,BoxFaceColor='k',BoxFaceAlpha=0.1); % box %[output:2ca49670]
hb.Parent.XAxis.Visible='off'; %[output:2ca49670]
grid on %[output:2ca49670]

title("Right Skewed") %[output:2ca49670]
%[text] - The swarm chart swells in the skewed region of the distribution \
%%
%[text] ### Violin chart
%[text] The shape of the swarm chart looks skewed
figure(Visible="on") %[output:94c7c754]
tiledlayout("horizontal") %[output:94c7c754]

nexttile % Plot Left Skewed Data %[output:94c7c754]
hold on %[output:94c7c754]
swarmchart(ones(1,numel(left.x)),left.x,'filled',MarkerFaceAlpha=0.5) % swarm %[output:94c7c754]
hb = violinplot(ones(1,numel(left.x)),left.x); % violin %[output:94c7c754]
hb.Parent.XAxis.Visible='off'; %[output:94c7c754]
grid on %[output:94c7c754]
title("Left Skewed") %[output:94c7c754]

nexttile % Plot Right Skewed Data %[output:94c7c754]
hold on %[output:94c7c754]
swarmchart(ones(1,300),right.x,'filled',MarkerFaceAlpha=0.5) % swarm %[output:94c7c754]
hb = violinplot(ones(1,300),right.x); % violin %[output:94c7c754]
hb.Parent.XAxis.Visible='off'; %[output:94c7c754]
grid on %[output:94c7c754]

title("Right Skewed") %[output:94c7c754]
