%[text] ### 
%%
url = 'https://raw.githubusercontent.com/salcedoe/MtMdocs/refs/heads/main/docs/dataProcessing/class.csv';
T = readtable(url);
T.Name = string(T.Name); % typecast to string
T.Sex = categorical(T.Sex) % typecast to categorical %[output:875d1291]
%%
figure; %[output:98bb09b9]
mmBoxSwarm(T.Sex, T.Height,XJitterWidth=0.25) %[output:98bb09b9]

